import math

# Function to compute nth Fibonacci number using matrix exponentiation
def multiply(F, a, b):
    return [[F[0][0] * a + F[0][1] * b, F[0][0] * b - F[0][1] * a],
            [F[1][0] * a + F[1][1] * b, F[1][0] * b - F[1][1] * a]]

def power(F, n):
    a = [[1, 1], [1, 0]]
    result = [[1, 0], [0, 1]]
    while n:
        if n & 1:
            result = multiply(result, a)
        a = multiply(a, a)
        n >>= 1
    return result

# Function to find k modulo p
def modInverse(a, p):
    g, x, y = extended_gcd(a, p)
    if g != 1:
        return -1
    return x % p

# Function to find the power in the power set
def powerModInverse(a, n, p):
    return multiply(power([1, 0], n), modInverse(a, p))[0][0] % p

# Extended Euclidean Algorithm
def extended_gcd(a, b):
    if b == 0:
        return (a, 1, 0)
    else:
        g, x, y = extended_gcd(b, a % b)
        return (g, y, x - (a // b) * y)

