        nonlocal min_steps, result
        if len(path) % 2 == 0:
            min_steps = min(min_steps, 2 * len(path) // 2)
        visited.add(v)
        path.append(v)
        for neighbor in graph[v]:
            if neighbor not in visited:
                dfs(neighbor, path)
        result.append(path)

    for v in range(1, N + 1):
        if v not in visited:
            dfs(v, [])

    return min_steps, result

