    m, n = len(x), len(y)
    i, j = 0, 0
    low = int(1e8)
    inf = 2147483647
    p1, q1 = -inf, -inf
    p2, q2 = inf, inf
    dist = float('inf')
    while i < m and j < n:
        px, py = x[i], y[j]
        if px < q1:
            if px < p1:
                p1, q1 = px, py
            elif px == p1 and py > q1:
                q1 = py
            else:
                low = px
                dist = min(dist, low - p1)
        elif px == q1:
            q1 = px
        i += 1

        if py < q2:
            if py < p2:
                p2, q2 = py, px
            elif py == p2 and px > q2:
                q2 = px
            else:
                low = py
                dist = min(dist, low - p2)
        elif py == q2:
            q2 = py
        j += 1

    return dist if dist != float('inf') else 0


def solve(points):
