import sys

def initialize_max_flow(graph, s, t):
    flow = {u: {} for u in range(1, n + 1)}
    paths = {}
    f = 0
    pq = [(0, s)]
    while pq:
        c, u = heapq.heappop(pq)
        if u == t:
            while u in paths:
                v = paths[u]
                flow[v][u] = min(flow[v][u], c)
                c = max(c, 0)
                paths.pop(u)
        for v, cap in graph[u].items():
            limit = cap - flow[v][u]
            if limit > 0:
                if v not in flow or c < flow[v][u]:
                    heapq.heappush(pq, (limit, v))
                    flow[v][u] = limit
    return {s: {t: f} + flow}

def max_flow_increase_edge(graph, u, v, cap):
    old_flow = 0
    paths = initialize_max_flow(graph, 1, len(graph) + 1)
    f = 0
    while paths[u][v] < cap and len(graph[u]) > 0:
        next_upstream = paths[u][v]
        while paths[v][1] > next_upstream:
            v = paths[v][1]
        u = v
        paths = initialize_max_flow(graph, 1, len(graph) + 1)
    return f

def query_flow(graph, s, t, seq):
    flow = 0
    for i in range(n):
        currents = load_data()
        new_filled_flow = max_flow_increase_edge(graph, s, i + 1, currents)
        flow += new_filled_flow
        x.append(new_filled_flow)
    x.append(flow)
    return x

def load_data():
    currents = 0
    for s in seq:
        for v in graph[s]:
            currents += max(0, v - s)
    return currents
