def evaluate_gate(w: int, gate: str, a: int, b: int) -> int:
    bits = list(bin(a)[2:])
    gate_str = gate[:2]

    if gate_str == 'AA':
        return (b & ((1 << w) - 2)) != 0

    if gate_str == 'X':
        return (b >> 1) ^ (b & a % 2)

    if gate_str == 'a':
        return (((b & 1) ^ (a & 1))) * 2 + (a & 2)

    if gate_str == 'o':
        return (2 * (b & a)) % 2
    if gate_str == 'x':
        return (((b ^ a) & 1) * 2 + (b & a)) != 0

def count_zero_outcomes(w: int, gates: List[str], registers: List[int]) -> List[int]:
    results = [0] * len(gates)
    for i, gate in enumerate(gates):
        mask = 1 << (w - 1)
        gate_results = list(accumulate([
            evaluate_gate(w, g, reg, registers[i]) << (i + j if j < i else j)
            for j, g in enumerate(gate)
        ], initial=0))
        results[i] = int(w*'0' + ''.join(map(str, gate_results)))

    for i, result in enumerate(results):
        print(results[i] if result == 0 else "" if results[i] & mask else "*")
