from heapq import heappush, heappop, heapify
from math import sqrt
from collections import Counter

def nth_term(n, k):
    heap = []
    count = Counter()
    for x in range(1, n + 1):
        count[x] += 1
        heappush(heap, -x)
        if len(heap) == k:
            heappop(heap)
        if heap[0] == -x:
            return -x, 1
    return -1, len(count)

def find_greatest_index(n, k):
    index, count = nth_term(n, k)
    if index == -1 or index > n:
        return -1
    return index + 1 + (count[count.index(n)] - 1) * k + 1

