from collections import defaultdict

def apply_gate(bit_x, bit_y, gate):
    gate_dict = {
        "A": lambda x, y: x & y,
        "O": lambda x, y: x | y,
        "X": lambda x, y: x ^ y,
        "a": lambda x, y: 1 if gate[0] else x & y,
        "o": lambda x, y: 1 if gate[1] else x | y,
        "x": lambda x, y: 1 if gate[2] else x ^ y,
    }
    if gate in gate_dict:
        return gate_dict[gate](bit_x, bit_y)
    return 0

def count_zero_inputs(a, e1, e2, gate):
