def solve(n: int, m: int, city_edges: List[int], citizens: List[int]) -> List[int]:
    graph = build_graph(n, city_edges)
    num_puppies = 0
    city_to_puppers = defaultdict(int)
    for city in range(1, n + 1):
        p = [0] * (n + 1)
        p[city] = 1
        work_path = shortest_path(graph, city, 0, n)
        for i in work_path:
            if i not in city_to_puppers:
                city_to_puppers[i] = 0
            if i > city:
                city_to_puppers[i] += 1
        if num_puppies < city_to_puppers[city]:
            num_puppies = city_to_puppers[city]
            max_city = city
    num_puppies = min(num_puppies, m)
    ans = []
    citizen_pup = [0] * m
    for p_list in list(city_to_puppers.values()):
        if p_list > num_puppies:
            citizen_pup[-1 - num_puppies] = p_list - num_puppies
        else:
            citizen_pup = 0
            break
    # Assign puppies to citizens
    for i in citizens:
        ans.append(citizen_pup[i - 1])
    # Assign puppies to guardians
    for i in range(num_puppies):
        city = citizens[i] - 1
        ans.append(city_to_puppers[city] - i)
    return ans

def shortest_path(graph, start, target, n) -> List[int]:
    path = [-1] * n + [start]
    visited = [False] * n
    visited[start] = True
    queue = [(0, start)]
    res = []
    while queue:
        dist, node = queue.pop(0)
        if node == target:
            break
        for neighbor in graph[node]:
            if not visited[neighbor]:
                visited[neighbor] = True
                queue.append((dist + 1, neighbor))
                path[neighbor] = 1
    # Convert path to shortest path
    path.remove(-1)
    s = set()
    for i in range(1, n + 1):
        if path[(path.index(i) - 1) % n] is not None or path[(path.index(i) - 1) % n - 1] is not None:
            continue
        for j in range(i, n):
            if path[(j - 1) % n] is not None:
                s.add(path[(path.index(j) - 1) % n])
                break
        for j in range(j + 1, n):
            if path[(j - 1) % n] is not None or path[(j - 1) % n + 1] is not None:
                continue
            if (i != j) and (path[(path.index(j) - 1) % n] not in s) and path[(path.index(j) - 1) % n] is not None:
                s.add(path[(path.index(j) - 1) % n])
                break
    return path

