import collections

def update_table(table, row, col, value):
    """Updates a specific position in the table."""
    if row:
        table[row][col] = value
        for i in range(row, len(table)):
            table[i][col] = sum(table[i-1][max(0, col-j-1) : col+1] for j in range(col))
    if col:
        for i in range(row, len(table)):
            for j in range(col, max(col, 1)):
                table[i][j] = sum(table[max(0, i-j-1) : i+1][j-1] for j in range(1, min(col, i)+1))
                table[i][j] += table[row-1][j-1]
        table[row][-1] = value
    return table

