    """Rebuilds the table starting from a given row and col, and returns the value in the given position."""
    for i in range(row):
        if table[i][count] == 0:
            return retrieve_password(table, i + 1, 0, count+1)
        return table[i][count]
    table[row][-1] = retrieve_password(table, row, col, count=0)
    return table[row][-1]

