import sys

def min_area_rect(points):
    def intersects(p, q):
        return max(p[0], q[0]) < min(p[1], q[1])

    points.sort()
    min_area = float('inf')
    n = len(points)

    for i in range(n):
        for j in range(i+1, n):
            if not intersects(points[i], points[j]):
                x0, y0 = min(*points[i]), max(*points[i])
                x1, y1 = min(*points[j]), max(*points[j])

                if y0 == y1:
                    x = x0
                    if j < n - 1:
                        while intersects(points[i+1], (x, y0)):
                            x += 1
                    else:
                        while intersects(points[0], (x, y0)):
                            x += 1
                    areas = [
                        abs(x0 - x) * abs(y0) * len(points[j]),
                        abs(x1 - x) * abs(y1) * len(points[j]),
                        abs(y0 - y1) * abs(x0) * len(points[i]),
                        abs(y1 - y0) * abs(x1) * len(points[i])
                    ]
                    min_area = min([min_area] + areas)

