def paintCave(n, m):
    # Initialize variables
    dp = [[0 for _ in range(m + 1)] for _ in range(n + 1)]
    dp[1][1] = 1

    # Base case: only one column and one row
    start = 3
    x = 3
    for i in range(1, start + 1):
        for j in range(1, m + 1):
            dp[i][j] = 1
    x = 4
    for i in range(1, n + 1):
        for j in range(1, m + 1):
            dp[i][j] = ((dp[i - 1][j - 1] - dp[i - 1][j]) * x + dp[i][j - 1]) % MOD
        x += 3

    return (pow(2, m, MOD) - 2 * (dp[n][m] - 1) + 1) % MOD

