        u = q.popleft()

        for v, edg, cap in edges[u]:
            if dist[v] == -1 and edg[v][u] + cap > 0:
                dist[v] = dist[u] + 1
                q.append(v)

def dfs(u, to):
    if u == to:
        return edg[to][u][2]
    for v, edg, cap in reversed(edges[u]):
        res = 0
        if dist[v] == dist[u] + 1 and edg[v][u] > 0:
            res += dfs(v, to)
            res = min(res, cap)
            edg[v][u] -= res
            edg[u][v] += res
            if edg[v][u] == 0:
                dist[v] = -1
            if edg[u][v] + cap - res == 0:
                res = sima(u, to, v)
            if edg[u][v] + cap - res == 0:
                return res
    return 0

def sima(u, v, to):
    if dist[u] > dist[v]:
        u, v = v, u
    return -min(res / 2 for res in (dfs(u, to), dfs(u, to)) if dist[u] == dist[v] + 1)

def solve(k, queries):
