from collections import deque

def get_graph_and_steps(n, m):
    graph = [[] for _ in range(n + 1)]
    for _ in range(m):
        u, v = map(int, input().split())
        graph[u].append(v)
    return graph, [int(input()) for _ in range(m)]

def topological_sort(graph):
    indegree = [0] * (len(graph) + 1)
    for u in range(len(graph)):
        for v in graph[u]:
            indegree[v] += 1
    zero_indegree = deque([v for v in range(len(graph)) if indegree[v] == 0])
    sorted_cycles = [0] * len(graph)

    while zero_indegree:
        u = zero_indegree.popleft()
        sorted_cycles[u] = len(zero_indegree)
        for v in graph[u]:
            indegree[v] -= 1
            if indegree[v] == 0:
                zero_indegree.append(v)

    # Check if graph is cyclic
    for i in range(1, len(graph)):
        if sorted_cycles[i] < i:
            return 'Incorrect topological sort', []

    return 'Cycle found in graph', sorted_cycles

def is_planar(graph, steps):
    for i in range(1, len(graph)):
        if steps[i] == 1:
            return False
    return True

