import sys

def solve(matrix, l, r):
    columns = len(matrix[0])
    rows = len(matrix)
    height = [[0 for _ in range(cols)] for _ in range(rows)]

    def dfs(i, j):
        for x, y in [(0, -1), (-1, 0), (0, 1), (1, 0)]:
            ni, nj = i + x, j + y
            if 0 <= ni < rows and 0 <= nj < columns and height[i][j] < height[ni][nj]:
                height[ni][nj] = height[i][j] + 1
                dfs(ni, nj)

    dfs(0, 2)
    result = 0

    for _ in range(r - l + 1):
        mid = l + ((r - l) >> 1)
        if columns & 1:
            upper = 0
        else:
            upper = 5 * height[l][mid-1] + 1 + mid * columns
        if rows & 1:
            lower = 0
        else:
            lower = 5 * height[l[mid+1]][mid] + 1 + mid * columns
        if upper < lower:
            mid += 1
        result += height[mid][mid]
        l = mid

    return result

n, m, q = map(int, input().split())
